"""Editorial content for CC-13, Civil Code arts. 1721-1828."""

def make(article, rule, effect, warning, term):
    return {
        "target": None,
        "o_que_diz": rule,
        "o_que_significa": effect,
        "exemplo_pratico": f"Em situação relacionada ao art. {article}, a solução deve observar {term.lower()} e as condições específicas descritas na regra.",
        "atencao": warning,
        "palavras_dificeis": [{"termo": term, "explicacao": effect}],
    }

SPECS = {
"1721":("O fim da sociedade conjugal, por si só, não elimina o bem de família voluntário.","A proteção patrimonial continua apesar da separação ou do divórcio, enquanto não ocorrer causa legal de extinção.","Dissolução conjugal não equivale automaticamente ao cancelamento registral ou à perda da proteção.","Bem de família"),
"1722":("O bem de família termina com a morte dos dois cônjuges e a maioridade dos filhos que não estejam sujeitos a curatela.","A proteção persiste enquanto houver filho menor ou curatelado e cessa quando se completarem cumulativamente as condições legais.","A maioridade isolada de um filho não basta se outro beneficiário continuar protegido.","Extinção do bem de família"),
"1723":("A união estável exige convivência pública, contínua, duradoura e orientada à constituição de família; impedimentos matrimoniais, em regra, obstam seu reconhecimento.","O vínculo familiar decorre da realidade da convivência, sem prazo mínimo, e alcança casais do mesmo sexo pela interpretação constitucional.","Pessoa casada pode constituir união estável se estiver separada de fato ou judicialmente; namoro qualificado não basta sem intenção familiar presente.","União estável"),
"1724":("Companheiros devem lealdade, respeito, assistência e cuidado material e educacional com os filhos.","A união estável produz deveres pessoais recíprocos e responsabilidades parentais, sem hierarquia entre os conviventes.","Os deveres parentais pertencem a ambos e não desaparecem com o fim da convivência.","Deveres dos companheiros"),
"1725":("Sem contrato escrito, as relações patrimoniais da união estável seguem, no que couber, a comunhão parcial.","Em regra comunicam-se aquisições onerosas feitas durante a convivência, preservadas as exclusões legais e eventual pacto válido.","Contrato de convivência e efeitos perante terceiros exigem análise própria; não se presume comunicação de todo patrimônio.","Comunhão parcial"),
"1726":("Os companheiros podem converter a união estável em casamento mediante requerimento e registro civil.","A conversão formaliza o casamento sem apagar a história da convivência, observados procedimento e requisitos registrais atuais.","A disciplina procedimental pode ser administrativa segundo as normas registrais, apesar da referência literal ao juiz.","Conversão em casamento"),
"1727":("A convivência não eventual entre pessoas impedidas de casar é qualificada pelo Código como concubinato.","A regra distingue concubinato de união estável, mas sua aplicação deve respeitar a proteção constitucional, a boa-fé e situações familiares concretas.","Não se deve usar o rótulo para negar automaticamente todo efeito obrigacional ou proteção de pessoas vulneráveis.","Concubinato"),
"1728":("A tutela protege menor cujos pais morreram, foram declarados ausentes ou perderam o poder familiar.","Na falta de responsável parental, um tutor assume cuidado pessoal e administração patrimonial sob fiscalização judicial.","A tutela não se confunde com adoção e não cria filiação.","Tutela"),
"1729":("A nomeação de tutor cabe conjuntamente aos pais e deve constar de testamento ou documento autêntico.","A escolha parental é preferencial quando ambos conservam poder familiar e a formalizam validamente.","A indicação não dispensa controle de validade e aptidão do nomeado.","Tutela testamentária"),
"1730":("É inválida a escolha de tutor feita por genitor que, ao morrer, já não exercia poder familiar.","Quem perdeu a autoridade parental não pode projetar para depois da morte uma escolha fundada nessa autoridade.","Suspensão ou perda do poder familiar deve ser verificada no momento do falecimento.","Poder familiar"),
"1731":("Sem tutor indicado pelos pais, a tutela recai preferencialmente em ascendentes e depois em colaterais até terceiro grau, conforme proximidade e aptidão.","A ordem de parentesco orienta a escolha, mas o interesse do menor permite ao juiz selecionar quem ofereça melhor proteção.","Proximidade familiar não cria direito absoluto ao encargo.","Tutela legítima"),
"1732":("O juiz escolhe tutor idôneo residente no domicílio do menor quando faltarem nomeação parental e parente apto, ou quando houver exclusão destes.","A tutela dativa supre a ausência de pessoa preferencial adequada.","Idoneidade e melhor interesse do menor prevalecem sobre conveniência do candidato.","Tutor dativo"),
"1733":("Irmãos órfãos devem, em regra, ficar sob um único tutor, respeitadas nomeações parentais distintas e a possibilidade de unificação judicial.","A unidade de tutela favorece cuidado coerente e preservação dos vínculos fraternos.","A regra admite adaptação quando instrumentos parentais ou interesses concretos exigirem solução diversa.","Unidade da tutela"),
"1734":("Menores sem cuidado parental recebem tutor judicial ou colocação familiar conforme o Estatuto da Criança e do Adolescente.","A proteção deve integrar o regime civil às medidas especiais de convivência familiar previstas no ECA.","A institucionalização não é resposta automática e a legislação especial orienta a solução protetiva.","Colocação familiar"),
"1735":("São impedidos de exercer tutela, entre outros, quem não administra livremente seus bens, tem conflito com o menor, inimizada, condenação relevante ou conduta incompatível.","O rol afasta pessoas cuja incapacidade, conflito ou falta de idoneidade possa comprometer o tutelado.","O impedimento pode provocar exoneração mesmo depois de iniciado o encargo.","Incapacidade para tutela"),
"1736":("Podem pedir dispensa da tutela as pessoas nas situações pessoais enumeradas, como idade avançada, enfermidade, muitos filhos ou encargo público relevante.","A escusa protege quem teria dificuldade legalmente reconhecida para assumir o encargo.","A dispensa depende de alegação tempestiva e apreciação competente.","Escusa da tutela"),
"1737":("Pessoa sem parentesco não precisa aceitar tutela se houver parente idôneo no local e apto a exercê-la.","A existência de familiar adequado afasta a imposição do encargo a estranho.","A mera existência de parente não basta se ele não for idôneo ou não tiver condições.","Tutor estranho"),
"1738":("A escusa deve ser apresentada em dez dias da designação ou do surgimento posterior do motivo.","O silêncio no prazo faz perder a possibilidade de usar aquele fundamento para recusar o encargo.","O termo inicial muda quando a causa de escusa aparece depois da aceitação.","Prazo de escusa"),
"1739":("Se a escusa for recusada, o nomeado continua exercendo a tutela durante o recurso e responde por danos causados ao menor.","A impugnação não suspende automaticamente a proteção, evitando que o tutelado fique sem responsável.","A responsabilidade decorre da atuação danosa, não da simples apresentação do recurso.","Efeito não suspensivo"),
"1740":("O tutor dirige educação, defesa e cuidado do menor, presta alimentos conforme recursos e comunica ao juiz fatos graves.","A função pessoal do tutor combina proteção cotidiana com dever de buscar intervenção judicial quando necessária.","Medidas graves contra o menor não podem ser tomadas arbitrariamente pelo tutor.","Cuidado tutelar"),
"1741":("O tutor administra o patrimônio do tutelado em benefício deste, com zelo, boa-fé e fiscalização judicial.","Os bens devem ser geridos exclusivamente conforme o interesse do menor e com transparência.","O tutor não pode tratar o patrimônio tutelado como próprio.","Administração tutelar"),
"1742":("O juiz pode nomear protutor para fiscalizar os atos do tutor.","O protutor acrescenta controle específico à supervisão judicial e pode detectar irregularidades.","Fiscalização não transfere automaticamente ao protutor a administração dos bens.","Protutor"),
"1743":("Com aprovação judicial, tarefas técnicas, complexas ou distantes podem ser parcialmente delegadas a pessoa especializada.","A delegação atende necessidades de gestão sem retirar do tutor a função principal e sua responsabilidade.","A transferência é parcial e depende de autorização; não equivale a abandonar o encargo.","Delegação parcial"),
"1744":("O juiz responde diretamente se não nomear tutor ou o fizer fora do tempo, e subsidiariamente se deixar de exigir garantia ou remover tutor suspeito.","Omissões judiciais específicas podem gerar reparação conforme a modalidade de responsabilidade prevista.","Responsabilidade direta e subsidiária têm pressupostos diferentes.","Responsabilidade judicial"),
"1745":("Os bens e valores do menor são entregues ao tutor mediante inventário formal, mesmo se os pais dispensaram essa providência.","O termo inicial permite controle posterior da administração e protege contra ocultação ou perda patrimonial.","Dispensa parental não elimina a documentação legal obrigatória.","Termo de bens"),
"1746":("Se o menor tiver patrimônio, seu sustento e educação podem ser custeados por ele em quantia fixada conforme rendimentos, salvo fixação parental válida.","A utilização deve ser proporcional e controlada, preservando o patrimônio enquanto atende necessidades do tutelado.","A existência de bens não autoriza gastos ilimitados.","Despesas do pupilo"),
"1747":("O tutor representa ou assiste o menor, recebe rendas, cobra créditos, paga despesas e promove conservação de seus bens.","São atos ordinários necessários à proteção pessoal, processual e patrimonial do tutelado.","Atos que excedem administração comum podem exigir autorização judicial específica.","Representação do tutelado"),
"1748":("Atos relevantes, como pagar certas dívidas, transigir, vender móveis ou imóveis e propor ações, dependem de autorização judicial.","O controle prévio reduz risco em decisões capazes de comprometer significativamente o patrimônio do menor.","A autorização deve atender vantagem ou necessidade do tutelado, não interesse do tutor.","Autorização judicial"),
"1749":("Nem com autorização o tutor pode adquirir bens do menor, dispor gratuitamente deles ou tornar-se cessionário de crédito contra ele.","A proibição absoluta evita autocontratação, liberalidades e conflitos patrimoniais estruturalmente perigosos.","A violação gera nulidade e não se cura pela mera concordância judicial.","Conflito de interesses"),
"1750":("Imóvel do tutelado só pode ser vendido com vantagem manifesta, avaliação prévia e aprovação judicial.","A alienação é excepcional e deve demonstrar benefício objetivo para o menor.","Preço conveniente sozinho não substitui avaliação e autorização formais.","Venda de imóvel tutelado"),
"1751":("Antes de assumir, o tutor deve declarar dívida que possua perante o menor, sob pena de não poder cobrá-la durante a tutela, salvo desconhecimento provado.","A revelação prévia impede que o tutor esconda posição de credor conflitante.","A exceção exige prova de desconhecimento real do débito.","Declaração de dívida"),
"1752":("O tutor indeniza danos causados por culpa ou dolo, recebe reembolso de gastos reais e pode ter remuneração proporcional, com responsabilidade solidária de quem colaborar no prejuízo.","O regime combina prestação responsável, ressarcimento legítimo e reparação integral do tutelado.","Remuneração e reembolso não afastam responsabilidade por má gestão.","Responsabilidade do tutor"),
"1753":("O tutor só conserva dinheiro suficiente às despesas ordinárias; o excedente deve ser depositado ou aplicado conforme determinação judicial.","A restrição reduz apropriação e mantém recursos protegidos e produtivos.","Necessidade futura não autoriza reter numerário além do montante prudente.","Depósito tutelar"),
"1754":("Valores depositados oficialmente só saem por ordem judicial para despesas, aquisição de bens, investimento ou outra finalidade autorizada.","A movimentação bancária é vinculada ao interesse do tutelado e submetida a controle prévio.","Saque sem ordem pode gerar responsabilidade, ainda que o tutor alegue boa intenção.","Levantamento judicial"),
"1755":("O tutor deve prestar contas mesmo que os pais tenham tentado dispensá-lo.","A fiscalização patrimonial é indisponível e protege o menor contra gestão opaca.","Cláusula de dispensa em testamento não elimina o dever legal.","Prestação de contas"),
"1756":("Anualmente o tutor apresenta balanço ao juiz para aprovação e juntada aos autos.","O controle periódico acompanha a evolução patrimonial antes da prestação completa de contas.","Balanço anual não substitui outras contas exigidas pela lei.","Balanço anual"),
"1757":("Contas completas são devidas a cada dois anos, no fim do encargo e sempre que o juiz determinar.","A periodicidade mínima não limita a fiscalização extraordinária diante de risco ou dúvida.","O término antecipado da tutela provoca prestação imediata.","Contas bienais"),
"1758":("Após maioridade ou emancipação, a quitação dada pelo ex-tutelado só vale depois da aprovação judicial das contas.","A responsabilidade do tutor continua até o controle final, evitando renúncia prematura do protegido.","A maioridade não convalida automaticamente administração irregular.","Quitação do tutelado"),
"1759":("Se o tutor morrer, desaparecer ou for interditado, seus herdeiros ou representantes prestam as contas.","O dever contábil acompanha o espólio ou representação e não se extingue com a impossibilidade pessoal do tutor.","Os sucessores prestam contas da gestão, não assumem automaticamente a tutela.","Sucessão do dever de contas"),
"1760":("Despesas justificadas e proveitosas ao menor são creditadas ao tutor.","A apuração reconhece gastos legítimos feitos no interesse do tutelado.","Despesa sem prova ou sem utilidade não gera reembolso automático.","Crédito do tutor"),
"1761":("As despesas necessárias à prestação de contas são suportadas pelo patrimônio do tutelado.","O custo regular do controle integra a administração protegida.","A regra não legitima custos abusivos causados por irregularidade do tutor.","Custo das contas"),
"1762":("Saldos reconhecidos contra tutor ou tutelado são dívidas de valor e recebem juros desde o julgamento definitivo das contas.","A decisão final define o saldo e o marco dos juros, preservando seu valor econômico.","Antes do julgamento podem existir controvérsias que impeçam tratar o saldo como definitivo.","Alcance do tutor"),
"1763":("A tutela termina para o tutelado com maioridade, emancipação, retorno ao poder familiar, reconhecimento ou adoção.","O encargo cessa quando desaparece a necessidade jurídica de representação tutelar.","Fim da tutela não dispensa acerto e aprovação das contas.","Cessação da tutela"),
"1764":("As funções do tutor terminam pelo fim do prazo, escusa aceita ou remoção.","O encerramento da função pessoal pode ocorrer mesmo que o menor ainda necessite de novo tutor.","Cessação do tutor e cessação da tutela são situações distintas.","Fim da função tutelar"),
"1765":("Em regra o tutor serve por dois anos, podendo continuar se o juiz considerar conveniente ao menor.","O prazo permite renovação da avaliação de aptidão sem impor troca prejudicial.","A prorrogação depende do interesse do tutelado, não de direito do tutor.","Prazo da tutela"),
"1766":("Tutor negligente, desleal ou legalmente incapaz deve ser removido.","A destituição protege o menor quando a permanência compromete cuidado ou patrimônio.","A medida exige procedimento adequado e não substitui eventual reparação de danos.","Remoção do tutor"),
"1767":("Curatela alcança quem não consegue exprimir vontade, dependentes habituais de álcool ou drogas e pródigos, nos limites necessários.","Após o Estatuto da Pessoa com Deficiência, a curatela é excepcional, proporcional e principalmente patrimonial, sem presumir incapacidade total.","Diagnóstico ou deficiência, isoladamente, não autoriza restrição ampla da capacidade.","Curatela"),
"1774":("As regras da tutela aplicam-se à curatela quando compatíveis e ressalvadas as adaptações específicas.","O regime tutelar funciona como disciplina subsidiária, ajustada à autonomia e necessidades da pessoa curatelada.","A remissão não permite ignorar o Estatuto da Pessoa com Deficiência.","Aplicação subsidiária"),
"1775":("Cônjuge ou companheiro não separado tem preferência como curador; na falta, seguem pai, mãe, descendente apto e escolha judicial.","A ordem orienta a nomeação, sempre subordinada à aptidão e aos interesses da pessoa curatelada.","Preferência familiar não é absoluta diante de conflito, violência ou inadequação.","Ordem de curadores"),
"1775-A":("O juiz pode instituir curatela compartilhada para pessoa com deficiência.","Mais de um curador pode dividir responsabilidades quando isso ampliar proteção e apoio sem restringir indevidamente a autonomia.","Competências e deveres devem ser definidos para evitar conflito entre curadores.","Curatela compartilhada"),
"1777":("A pessoa que não consegue exprimir vontade deve receber apoio para preservar convivência familiar e comunitária, evitando isolamento institucional.","A proteção prioriza inclusão, vínculos e medidas menos restritivas.","Acolhimento afastado da comunidade exige necessidade concreta, não mera conveniência.","Convivência comunitária"),
"1778":("A autoridade do curador alcança os filhos e bens dos filhos da pessoa curatelada, observadas as regras de capacidade.","A extensão busca assegurar cuidado familiar, mas deve ser lida com os limites atuais da curatela e do poder familiar.","Curatela do genitor não elimina automaticamente sua parentalidade.","Extensão da curatela"),
"1779":("Nomeia-se curador ao nascituro se o pai morrer durante a gravidez e a gestante não exercer poder familiar; se ela estiver curatelada, seu curador acumula a função.","A medida protege interesses patrimoniais do concebido antes do nascimento.","A curadoria do nascituro é específica e não antecipa personalidade plena.","Curador do nascituro"),
"1781":("Normas de exercício da tutela aplicam-se à curatela dentro das restrições legais e das regras especiais.","Administração, fiscalização e contas são aproveitadas apenas quando compatíveis com a curatela contemporânea.","Dispositivos revogados mencionados no texto não restauram limitações antigas.","Exercício da curatela"),
"1782":("O pródigo precisa de curador para atos patrimoniais relevantes, mas conserva autonomia para atos de mera administração.","A restrição é parcial e voltada a impedir dissipação patrimonial.","A curatela não retira direitos existenciais nem autoriza controle total da vida.","Prodigalidade"),
"1783":("Curador casado em comunhão universal com o curatelado dispensa contas, salvo se o juiz exigir.","A comunhão patrimonial justifica dispensa relativa, preservado o controle judicial diante de risco.","A exceção não impede responsabilização por abuso ou conflito.","Dispensa de contas"),
"1783-A":("Na decisão apoiada, pessoa com deficiência escolhe ao menos dois apoiadores confiáveis para auxiliá-la em atos civis, por procedimento judicial delimitado.","O apoio fornece informação e compreensão sem substituir a vontade da pessoa, que conserva capacidade; divergências e abusos recebem controle judicial.","Apoiado não é interditado, e apoiador não vira representante geral.","Tomada de decisão apoiada"),
"1784":("A herança passa imediatamente aos herdeiros legítimos e testamentários quando ocorre a morte.","O princípio da transmissão imediata evita patrimônio sem titular, embora inventário e partilha individualizem os quinhões.","Posse material dos bens não é requisito para adquirir a herança.","Saisine"),
"1785":("A sucessão considera-se aberta no último domicílio do falecido.","Esse local orienta a competência territorial do inventário e centraliza o procedimento sucessório.","A localização isolada de um bem não muda automaticamente o lugar da sucessão.","Lugar da sucessão"),
"1786":("A sucessão decorre da lei, de disposição de última vontade ou da combinação de ambas.","Herança pode seguir vocação legítima e testamento, cada qual sobre a parcela juridicamente disponível.","Testamento parcial deixa o restante sujeito à sucessão legítima.","Fonte da sucessão"),
"1787":("A lei vigente na data da morte rege a sucessão e a capacidade para suceder.","A abertura da sucessão fixa o direito intertemporal, mesmo que inventário e partilha ocorram depois.","Mudança legislativa posterior não altera automaticamente sucessão já aberta.","Lei sucessória no tempo"),
"1788":("Sem testamento válido e eficaz, ou quanto a bens não abrangidos, aplica-se a sucessão legítima.","A vocação legal completa ou substitui a vontade testamentária quando ela falta, caduca ou é inválida.","Nulidade de uma disposição não elimina necessariamente todo o testamento.","Sucessão legítima residual"),
"1789":("Com herdeiros necessários, apenas metade da herança pode ser livremente destinada por testamento.","A outra metade forma a legítima reservada aos descendentes, ascendentes e cônjuge, conforme o regime vigente.","A parte disponível é calculada sobre patrimônio líquido e pode sofrer redução se excedida.","Legítima"),
"1790":("O texto atribui ao companheiro regime sucessório próprio limitado a certos bens, mas essa diferenciação foi declarada inconstitucional em julgamento vinculante.","Na aplicação atual, a união estável segue a ordem do art. 1.829, como o casamento; a decisão alcança inventários sem partilha transitada e partilhas extrajudiciais ainda sem escritura.","Não se deve apresentar os incisos do artigo como regime atual geral nem dizer que houve revogação legislativa expressa.","Inconstitucionalidade sucessória"),
"1791":("Até a partilha, herança e quinhões formam unidade indivisível regida pelas regras de condomínio.","Cada herdeiro possui fração ideal do conjunto, não propriedade exclusiva de bem determinado.","Venda de bem singular exige observar administração do espólio e direitos dos demais.","Indivisão hereditária"),
"1792":("O herdeiro responde por dívidas somente até o valor herdado, cabendo-lhe demonstrar excesso quando o inventário não o revelar.","Patrimônio próprio fica protegido além das forças da herança.","A limitação não dispensa prova e apuração regular do acervo.","Forças da herança"),
"1793":("Direitos hereditários e quinhão podem ser cedidos por escritura pública, respeitadas limitações sobre bens singulares e direitos de coerdeiros.","A cessão transfere posição no acervo indiviso, não automaticamente domínio exclusivo de objeto específico.","Cessão gratuita ou onerosa exige forma pública e análise de preferência.","Cessão hereditária"),
"1794":("Coerdeiro tem preferência, em igualdade de condições, antes da cessão onerosa de quota a estranho.","A regra preserva o grupo hereditário e permite aquisição pelo mesmo preço.","Preferência incide sobre quota hereditária, não sobre toda alienação após partilha.","Preferência do coerdeiro"),
"1795":("Coerdeiro preterido pode depositar o preço e reclamar a quota cedida a estranho em até cento e oitenta dias.","A tutela substitui o adquirente quando faltou comunicação e o interessado age no prazo.","Havendo vários interessados, o quinhão é distribuído proporcionalmente.","Adjudicação da quota"),
"1796":("O Código manda instaurar inventário em trinta dias, mas o prazo procedimental atual deve ser lido com o Código de Processo Civil.","A abertura e conclusão do inventário seguem a lei processual vigente, que disciplina prazo, prorrogação e consequências.","Não se deve tratar o prazo civil antigo isoladamente quando o CPC contém disciplina específica posterior.","Prazo do inventário"),
"1797":("Antes do compromisso do inventariante, a herança é administrada sucessivamente por cônjuge ou companheiro convivente, herdeiro possuidor, testamenteiro ou pessoa designada.","A ordem garante gestão provisória até a nomeação formal do inventariante.","Administrador provisório deve conservar o acervo e prestar contas.","Administração provisória"),
"1798":("Podem suceder as pessoas nascidas ou concebidas quando a sucessão se abre.","A existência ou concepção no momento da morte é requisito geral de legitimação sucessória.","O nascituro recebe proteção condicional ao nascimento com vida.","Legitimação sucessória"),
"1799":("Testamento pode beneficiar filhos ainda não concebidos de pessoa indicada, pessoas jurídicas e fundações a serem criadas.","A vontade testamentária alcança beneficiários futuros dentro das condições e prazos legais.","A indicação precisa permitir identificar a pessoa de referência ou a finalidade fundacional.","Prole eventual"),
"1800":("Bens destinados à prole eventual ficam com curador; se o herdeiro esperado não for concebido em dois anos, passam aos herdeiros legítimos, salvo disposição diferente.","A curadoria preserva o patrimônio durante a espera e a lei impõe prazo supletivo.","Concepção e nascimento produzem efeitos conforme as regras do nascituro.","Curadoria da prole eventual"),
"1801":("Não podem receber por testamento quem o escreveu a rogo, testemunhas, certos agentes da aprovação, concubino em hipótese legal e tabelião envolvido.","As incompatibilidades evitam influência indevida e conflito na formação do testamento.","A vedação depende da posição concreta da pessoa no ato e das exceções legais.","Incapacidade testamentária passiva"),
"1802":("É nula a disposição feita direta ou simuladamente em favor de pessoa impedida, inclusive por interposta pessoa.","A lei alcança manobras destinadas a contornar incapacidade sucessória.","Ascendente, descendente, irmão ou cônjuge do impedido pode ser presumido intermediário nos casos legais.","Interposta pessoa"),
"1803":("É válida a disposição ao filho comum do testador e de pessoa em relação concubinária.","A incapacidade eventualmente atribuída ao genitor não contamina o direito autônomo do filho.","A filiação comum deve ser real, não mera interposição simulada.","Deixa testamentária"),
"1804":("A aceitação consolida a transmissão ocorrida na morte; a renúncia faz considerar que o renunciante nunca recebeu.","Aceitação e renúncia retroagem à abertura da sucessão com efeitos opostos.","Antes de optar, o herdeiro deve avaliar dívidas, forma e consequências para sua classe.","Efeito retroativo"),
"1805":("Aceitação pode ser escrita ou resultar de atos próprios de herdeiro; atos funerários, conservatórios ou de administração provisória não bastam.","A aceitação tácita exige comportamento incompatível com recusa, não simples cuidado urgente.","Cessão gratuita a todos os coerdeiros pode ter tratamento distinto conforme a regra legal.","Aceitação tácita"),
"1806":("Renúncia exige declaração expressa em escritura pública ou termo judicial.","A solenidade impede renúncia presumida ou informal.","Silêncio e abandono de bens não equivalem à renúncia válida.","Renúncia solene"),
"1807":("Após vinte dias da abertura, interessado pode pedir que o juiz fixe até trinta dias para o herdeiro optar; o silêncio importa aceitação.","A interpelação encerra incerteza sucessória e atribui consequência legal à falta de resposta.","Os dois períodos têm funções diferentes e dependem de provocação judicial.","Prazo para deliberar"),
"1808":("Aceitação e renúncia não podem ser parciais, condicionais ou a termo, ressalvada autonomia entre legados e quinhões distintos.","A opção sobre a mesma herança é indivisível e pura, evitando seleção oportunista de bens.","Herdeiro também legatário pode decidir separadamente sobre títulos sucessórios diferentes.","Indivisibilidade da opção"),
"1809":("Se o herdeiro morrer antes de optar, seus sucessores recebem o poder de aceitar, salvo vocação sujeita a condição suspensiva ainda não cumprida.","Transmite-se o direito de deliberação junto com a sucessão do herdeiro falecido.","Os sucessores devem primeiro aceitar a herança daquele de quem receberam o poder.","Transmissão do direito de aceitar"),
"1810":("Na sucessão legítima, a quota renunciada acresce aos herdeiros da mesma classe ou passa à classe seguinte se não houver outro.","A renúncia reorganiza a vocação legal sem transmitir a quota como se fosse cessão.","Efeito varia conforme existam outros herdeiros da mesma classe.","Acréscimo por renúncia"),
"1811":("Não há representação de renunciante; seus filhos só sucedem por direito próprio se ele era único da classe ou todos nela renunciaram.","A lei distingue ocupar o lugar de alguém de ser chamado diretamente em nova configuração da classe.","Descendente do renunciante não recebe automaticamente a mesma quota por estirpe.","Direito próprio"),
"1812":("Aceitação e renúncia são irrevogáveis.","A opção válida estabiliza a sucessão e não pode ser desfeita por simples arrependimento.","Vícios do negócio podem ser discutidos, mas não equivalem a revogação voluntária.","Irrevogabilidade"),
"1813":("Credores prejudicados pela renúncia podem, com autorização judicial, aceitar em nome do herdeiro até o limite de seus créditos.","A medida combate fraude e preserva o excedente para os demais sucessores.","O pedido tem prazo legal e não transforma o credor em herdeiro além da satisfação devida.","Aceitação pelos credores"),
"1814":("Indignidade exclui herdeiro ou legatário por atentado grave, acusação caluniosa ou impedimento da liberdade de testar nas hipóteses legais.","A sanção sucessória protege autor da herança e autenticidade de sua vontade.","As causas são taxativas e exigem enquadramento e prova adequados.","Indignidade"),
"1815":("A exclusão por indignidade é declarada judicialmente, em regra dentro de quatro anos; o Ministério Público tem legitimidade no homicídio intencional previsto.","A sentença retira o sucessor indigno e o prazo estabiliza a sucessão.","O art. 1.815-A criou hipótese de exclusão imediata por condenação penal definitiva.","Ação de indignidade"),
"1815-A":("Condenação penal definitiva por hipótese de indignidade do art. 1.814 produz exclusão sucessória imediata, sem nova sentença civil constitutiva.","O trânsito penal basta para retirar herdeiro ou legatário quando o fato condenado coincide com causa legal de indignidade.","É indispensável correspondência entre condenação e hipótese legal; não é qualquer crime.","Exclusão automática"),
"1816":("A exclusão é pessoal: descendentes do indigno sucedem como se ele tivesse morrido antes, e o excluído não administra nem usufrui esses bens.","A sanção não contamina os descendentes e impede benefício indireto do excluído.","Representação dos descendentes não reabilita o indigno.","Efeitos pessoais"),
"1817":("Negócios onerosos com terceiros de boa-fé e administração anterior à exclusão são preservados, sem afastar indenização devida pelo excluído.","A segurança de terceiros convive com reparação aos sucessores prejudicados.","Má-fé do adquirente pode alterar a proteção do negócio.","Herdeiro aparente"),
"1818":("O ofendido pode reabilitar expressamente o indigno em testamento ou ato autêntico; disposição posterior, sabendo da causa, permite suceder no limite deixado.","O perdão válido restaura total ou parcialmente a capacidade sucessória conforme a manifestação do autor.","Reabilitação não é presumida do simples silêncio.","Reabilitação do indigno"),
"1819":("Sem testamento ou herdeiro conhecido, a herança é arrecadada e administrada por curador até habilitação ou vacância.","A herança jacente recebe guarda pública enquanto se procuram sucessores.","Jacência não transfere imediatamente bens ao poder público.","Herança jacente"),
"1820":("Após arrecadação, inventário e editais, a falta de habilitação por um ano permite declarar a herança vacante.","A vacância sucede fase de publicidade e busca por herdeiros.","Pedido de habilitação pendente impede declaração precipitada.","Herança vacante"),
"1821":("Credores podem receber dívidas reconhecidas até o limite do patrimônio hereditário.","Jacência ou vacância não apaga obrigações do falecido, mas preserva a limitação ao acervo.","Credor não alcança patrimônio de curador ou poder público por essa regra.","Credores da herança"),
"1822":("A vacância não prejudica habilitação oportuna, mas após cinco anos da morte os bens passam ao ente público competente conforme localização.","Há período legal para sucessores antes da incorporação definitiva ao domínio público.","Colaterais ficam excluídos se não se habilitarem até a declaração de vacância, conforme regra própria.","Devolução ao poder público"),
"1823":("Se todos os chamados renunciarem, a herança é declarada vacante imediatamente.","A renúncia universal elimina necessidade de esperar busca por herdeiros daquela vocação.","É preciso confirmar validade das renúncias e inexistência de sucessores chamados por direito próprio.","Vacância imediata"),
"1824":("A petição de herança permite ao verdadeiro herdeiro obter reconhecimento e restituição do acervo contra quem o possua com ou sem título hereditário.","A ação reúne declaração da qualidade sucessória e recuperação dos bens.","Questões de prescrição e boa-fé devem ser analisadas conforme jurisprudência e fatos.","Petição de herança"),
"1825":("Um único herdeiro pode pedir, em petição de herança, a restituição de todo o acervo.","A indivisibilidade anterior à partilha legitima atuação ampla em benefício da herança.","O resultado deve respeitar os quinhões dos demais sucessores.","Universalidade da ação"),
"1826":("Possuidor deve devolver o acervo, respondendo segundo boa ou má-fé e as regras gerais de posse.","Frutos, deteriorações, benfeitorias e indenização variam conforme seu estado subjetivo.","Boa-fé pode cessar quando o possuidor conhece a pretensão do verdadeiro herdeiro.","Restituição hereditária"),
"1827":("O herdeiro pode recuperar bens hereditários de terceiros, preservada a responsabilidade do possuidor originário pelo que alienou.","O caráter hereditário acompanha o bem, ressalvadas proteções legais específicas a terceiros.","Aquisição por terceiro deve ser examinada junto às regras de boa-fé e usucapião.","Perseguição do bem"),
"1828":("Herdeiro aparente de boa-fé que pagou legado não reembolsa o verdadeiro sucessor; este cobra de quem recebeu.","A boa-fé protege o pagamento realizado, deslocando a restituição ao beneficiário indevido.","Se o aparente agiu de má-fé, a solução pode ser diferente.","Pagamento de legado"),
}

ROWS={article:make(article,*spec) for article,spec in SPECS.items()}
EXPECTED={str(n) for n in range(1721,1829) if n not in {*range(1768,1774),1776,1780}}|{"1775-A","1783-A","1815-A"}
assert set(ROWS)==EXPECTED and len(ROWS)==103

